import { jsPDF } from 'jspdf';
var font =
  '';
var callAddFont = function () {
  this.addFileToVFS('AlibabaPuHuiTi-3-55-Regular-normal.ttf', font);
  this.addFont('AlibabaPuHuiTi-3-55-Regular-normal.ttf', 'AlibabaPuHuiTi-3-55-Regular', 'normal');
};
jsPDF.API.events.push(['addFonts', callAddFont]);
